style.css:
/* Removes various Discord elements for better visibility: */
[class^="wrapper_"],
[class^="guilds_"], /* Server List */
[class^="sidebar"],
[class^="buttons_"], /* Gif Buttons */
[class^="toolbar_"], /* Searchbar */
[class^="subtitleContainer_"], /* Channel Name Bar */
[class^="newMessagesBar_"]  /* Unread Messages */ {
    display: none;
}

/* Maximizes image size in the embed: */
[class^="embedWrapper_"]  {
    margin-left: -69px;
}

/* Adjusts padding for better text readability: */
[class^="message_"]  {
    padding-right: 0 !important
}
